<script setup>
import { computed, ref, reactive, watch } from 'vue';
import { Head, Link, router, usePage } from '@inertiajs/vue3';
import AppLayout from '../../layouts/AppLayout.vue';
import HubNav from './HubNav.vue';
import ContactChannels from './ContactChannels.vue';
import './hub.css';
const props=defineProps({leads:Object,filters:Object,stats:Object,options:Object});
const page=usePage();const user=computed(()=>page.props.auth.user);
const presets=[['manual','Ручной поиск'],['hot','Горячие лиды'],['it','Руководители IT'],['messenger','Лиды для мессенджера'],['procurement','Закупки и тендеры'],['free','Свободные лиды'],['due','Повторные касания'],['duplicates','Возможные дубли'],['quality','Проверка качества']];
const fresh=()=>({q:'',company:'',company_mode:'contains',titles:['','',''],title_mode:'contains',groups:[],holding:'',industry:'',status:'',priority:'',owner:'',min_score:0,email:false,phone:false,messenger:false,social:false,check:false,preset:'manual',company_id:''});
const state=reactive(fresh());
function sync(){Object.assign(state,fresh(),props.filters);state.titles=[...(props.filters.titles||[]),'','',''].slice(0,3);for(const k of ['email','phone','messenger','social','check'])state[k]=['1',1,true].includes(state[k]);}
sync();watch(()=>props.filters,sync,{deep:true});
const advanced=ref(false);const busy=ref(false);const error=ref('');const detail=ref(null);const addOpen=ref(false);const saving=ref(false);
const edit=reactive({version:0,status:'Новый',priority:'Не назначен',next_action:'',next_at:'',comment:'',take:false,owner_id:''});
const blank=()=>({full_name:'',company_raw:'',title:'',email:'',phone:'',messenger:'',social:''});
const newLead=reactive(blank());
const identityOpen=ref(false);const identity=reactive(blank());
const canIdentity=computed(()=>detail.value&&(user.value.role==='admin'||Number(detail.value.owner_id)===Number(user.value.id)));
function startIdentity(){for(const k of Object.keys(identity))identity[k]=detail.value[k]||'';identityOpen.value=true;error.value='';}
async function saveIdentity(){saving.value=true;error.value='';try{const id=detail.value.id;await api('/projects/sales-hub/leads/'+id+'/identity',{method:'PATCH',body:JSON.stringify({...identity,version:detail.value.version})});identityOpen.value=false;router.reload({only:['leads','stats']});await open(id);}catch(e){error.value=e.message;}finally{saving.value=false;}}
function exportLeads(){if(user.value.role!=='admin')return;const p=new URLSearchParams();for(const [k,v] of Object.entries(query())){if(k==='page')continue;if(Array.isArray(v))v.forEach(x=>p.append(k+'[]',x));else p.set(k,v);}window.location.assign('/projects/sales-hub/export?'+p);}
const assignment=ref(null);const assignBusy=ref(false);const assignError=ref('');const success=ref('');
const free=x=>!x.owner_id&&['','Не назначен'].includes(x.owner_raw);
const canAssign=x=>user.value.role==='admin'||free(x);
function startAssign(x){assignment.value={id:x.id,version:x.version,name:x.full_name||'Контакт #'+x.id,owner:x.owner_id??(free(x)?user.value.id:'')};assignError.value='';success.value='';}
async function assign(x,owner){
 if(assignBusy.value)return;
 assignBusy.value=true;assignError.value='';error.value='';success.value='';
 try{
  await api('/projects/sales-hub/leads/'+x.id+'/owner',{method:'PATCH',body:JSON.stringify({version:x.version,owner_id:owner===''||owner===null?null:Number(owner)})});
  assignment.value=null;success.value=owner===null||owner===''?'Ответственный снят':'Ответственный назначен';
  if(detail.value?.id===x.id)await open(x.id);
  router.reload({only:['leads','stats']});
 }catch(e){assignError.value=e.message;if(!assignment.value)error.value=e.message;}
 finally{assignBusy.value=false;}
}
const num=v=>Number(v||0).toLocaleString('ru-RU');
function query(p=1){const d={...state,page:p};for(const k of ['email','phone','messenger','social','check'])d[k]=d[k]?1:0;d.titles=d.titles.filter(Boolean);for(const k of Object.keys(d))if(d[k]===''||d[k]===null||d[k]===undefined||Array.isArray(d[k])&&!d[k].length)delete d[k];return d;}
function search(p=1){router.get('/projects/sales-hub',query(p),{preserveScroll:true,preserveState:true,replace:true,onStart:()=>busy.value=true,onFinish:()=>busy.value=false});}
function preset(v){state.preset=v;search();}
function reset(){Object.assign(state,fresh());search();}
async function api(url,opts={}){const r=await fetch(url,{...opts,credentials:'same-origin',headers:{Accept:'application/json','Content-Type':'application/json','X-CSRF-TOKEN':page.props.csrfToken}});const d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.message||'Ошибка запроса: '+r.status);return d;}
const canEdit=computed(()=>detail.value&&(user.value.role==='admin'||Number(detail.value.owner_id)===Number(user.value.id)));
const isFree=computed(()=>detail.value&&!detail.value.owner_id&&['','Не назначен'].includes(detail.value.owner_raw));
async function open(id){error.value='';try{const d=await api('/projects/sales-hub/leads/'+id);detail.value=d;identityOpen.value=false;Object.assign(edit,{version:d.version,status:d.status,priority:d.priority,next_action:d.next_action,next_at:d.next_at||'',comment:d.comment,take:false,owner_id:d.owner_id||''});}catch(e){error.value=e.message;}}
async function save(){saving.value=true;error.value='';try{const data={...edit,next_at:edit.next_at||null};delete data.owner_id;delete data.take;await api('/projects/sales-hub/leads/'+detail.value.id,{method:'PATCH',body:JSON.stringify(data)});detail.value=null;router.reload({only:['leads','stats']});}catch(e){error.value=e.message;}finally{saving.value=false;}}
async function create(){saving.value=true;error.value='';try{const d=await api('/projects/sales-hub/leads',{method:'POST',body:JSON.stringify(newLead)});addOpen.value=false;Object.assign(newLead,blank());router.reload({only:['leads','stats']});await open(d.id);}catch(e){error.value=e.message;}finally{saving.value=false;}}
function scoreClass(n){return n>=80?'a':n>=60?'b':n>=40?'c':'d';}
</script>
<template><Head title="Контакты"/><AppLayout><div class="saleshub"><HubNav/><div class="page-head"><div><p class="eyebrow">ЛИДОГЕНЕРАЦИЯ</p><h1>Рабочая база</h1><p class="muted">Поиск, отбор и работа с ЛПР</p></div><div class="actions"><button v-if="user.role==='admin'" @click="exportLeads">Экспорт CSV</button><button class="primary" @click="addOpen=true;error=''">+ Контакт</button></div></div>
<div class="metrics"><div v-for="[label,value] in [['Всего контактов',stats.total],['Есть канал связи',stats.reachable],['Горячие лиды',stats.hot],['Свободные',stats.free]]" :key="label" class="metric"><small>{{label}}</small><strong>{{num(value)}}</strong></div></div>
<div class="panel filters"><div class="preset-row"><button v-for="[v,label] in presets" :key="v" :class="{active:state.preset===v}" @click="preset(v)">{{label}}</button></div><p v-if="state.preset!=='manual'" class="muted">Сценарий заменяет ручные условия; фильтр ответственного остаётся активным.</p>
<form @submit.prevent="state.preset='manual';search()"><div class="filter-grid"><label>Поиск<input v-model="state.q" placeholder="ФИО, компания, должность"></label><label>Компания<input v-model="state.company" placeholder="Например, Сбер"></label><label>Должность<input v-model="state.titles[0]" placeholder="CIO, CTO"></label><label>Ответственный<select v-model="state.owner" @change="search()"><option value="">Все</option><option value="mine">Мои лиды</option><option value="free">Свободные</option><option v-for="o in options.owners" :key="o.id" :value="String(o.id)">{{o.name}}</option></select></label></div>
<div v-if="advanced" class="filter-grid advanced"><label>Режим компании<select v-model="state.company_mode"><option value="contains">Содержит</option><option value="exact">Точное совпадение</option></select></label><label>Должность 2<input v-model="state.titles[1]"></label><label>Должность 3<input v-model="state.titles[2]"></label><label>Режим должности<select v-model="state.title_mode"><option value="contains">Содержит</option><option value="exact">Точное совпадение</option></select></label><label>Группа ЛПР (ИЛИ)<select v-model="state.groups" multiple size="4"><option v-for="g in options.groups" :key="g">{{g}}</option></select></label><label>Холдинг<select v-model="state.holding"><option value="">Любой</option><option v-for="h in options.holdings" :key="h">{{h}}</option></select></label><label>Отрасль<select v-model="state.industry"><option value="">Любая</option><option v-for="i in options.industries" :key="i">{{i}}</option></select></label><label>Статус<select v-model="state.status"><option value="">Любой</option><option v-for="s in options.statuses" :key="s">{{s}}</option></select></label><label>Приоритет<select v-model="state.priority"><option value="">Любой</option><option v-for="p in options.priorities" :key="p">{{p}}</option></select></label><label>Минимальный балл<input v-model.number="state.min_score" type="number" min="0" max="100"></label><div class="checks"><label v-for="[key,label] in [['email','Почта'],['phone','Телефон'],['messenger','Мессенджер'],['social','Соцсети'],['check','На проверку']]" :key="key"><input type="checkbox" v-model="state[key]"> {{label}}</label></div></div>
<div class="actions"><button class="primary" :disabled="busy">Найти</button><button type="button" @click="advanced=!advanced">{{advanced?'Свернуть':'Расширенный поиск'}}</button><button type="button" @click="reset">Сбросить</button></div></form></div>
<div v-if="success" class="notice success" role="status">{{success}}</div><div v-if="error&&!detail&&!addOpen" class="notice error">{{error}}</div><div class="result-head"><strong>{{num(leads.total)}} контактов</strong><div class="actions"><button :disabled="leads.current_page<=1" @click="search(leads.current_page-1)">←</button><span>{{leads.current_page}} / {{leads.last_page}}</span><button :disabled="leads.current_page>=leads.last_page" @click="search(leads.current_page+1)">→</button></div></div>
<div class="table-scroll"><table><thead><tr><th>Контакт</th><th>Компания</th><th>Должность</th><th>Балл</th><th>Статус</th><th>Ответственный</th><th>Связь</th></tr></thead><tbody><tr v-for="x in leads.data" :key="x.id"><td><button class="text-link" @click="open(x.id)">{{x.full_name}}</button><small v-if="x.possible_duplicate" class="warn">Возможный дубль</small><small v-if="x.quality_check" class="warn">Проверить данные</small></td><td><Link v-if="x.company_id" :href="'/projects/sales-hub/companies?id='+x.company_id">{{x.company_raw}}</Link><span v-else>—</span><small v-if="x.company_claimed" class="warn">Компания уже в работе</small></td><td>{{x.title||'—'}}<small>{{x.groups.join(' · ')}}</small></td><td><span :class="'score '+scoreClass(x.score)">{{x.score}}</span></td><td>{{x.status}}<small>{{x.priority}}</small></td><td class="owner-cell"><strong v-if="x.owner_id" :class="{'owner-mine':Number(x.owner_id)===Number(user.id)}">{{x.owner_name||x.owner_raw}}</strong><span v-else>{{free(x)?'Свободен':x.owner_raw}}</span><small>{{x.next_at||''}}</small><div class="owner-actions"><button v-if="free(x)" class="claim" :disabled="assignBusy||busy" @click="assign(x,user.id)">Взять себе</button><button v-if="canAssign(x)" class="assign-link" :disabled="assignBusy||busy" @click="startAssign(x)">{{free(x)?'Назначить':'Изменить'}}</button></div></td><td><ContactChannels :contact="x"/></td></tr><tr v-if="!leads.data.length"><td colspan="7" class="empty">Контакты не найдены</td></tr></tbody></table></div>
<div v-if="detail" class="overlay" @click.self="detail=null"><section class="drawer" role="dialog" aria-modal="true" aria-label="Карточка контакта"><div class="page-head"><div><p class="eyebrow">КОНТАКТ #{{detail.id}}</p><h2>{{detail.full_name}}</h2></div><button @click="detail=null" aria-label="Закрыть">×</button></div><p>{{detail.company_raw}} · {{detail.title}}</p><p v-if="detail.possible_duplicate" class="notice warn">Совпадение канала связи с другим контактом. Проверьте перед обращением.</p><p v-if="detail.company_claimed" class="notice warn">С компанией уже может работать коллега.</p><section class="contact-owner"><strong>Ответственный: {{free(detail)?'Свободен':detail.owner_name||detail.owner_raw}}</strong><div class="owner-actions"><button v-if="free(detail)" class="claim" :disabled="assignBusy" @click="assign(detail,user.id)">Взять себе</button><button v-if="canAssign(detail)" class="assign-link" :disabled="assignBusy" @click="startAssign(detail)">Назначить ответственного</button></div></section><ContactChannels :contact="detail" expanded/><details v-if="Object.keys(detail.source||{}).length"><summary>Источники и разночтения</summary><dl><template v-for="(v,k) in detail.source" :key="k"><dt>{{k}}</dt><dd>{{v||'—'}}</dd></template></dl></details><button v-if="canIdentity&&!identityOpen" @click="startIdentity">Редактировать контактные данные</button><form v-if="identityOpen" @submit.prevent="saveIdentity"><label v-for="[k,label] in [['full_name','ФИО'],['company_raw','Компания'],['title','Должность'],['email','Почта'],['phone','Телефон'],['messenger','Мессенджер'],['social','Соцсети']]" :key="k">{{label}}<input v-model="identity[k]" :required="k==='full_name'"></label><div class="actions"><button class="primary" :disabled="saving">Сохранить данные</button><button type="button" @click="identityOpen=false">Отмена</button></div></form><form v-else @submit.prevent="save"><fieldset :disabled="!canEdit||saving"><div class="filter-grid"><label>Статус<select v-model="edit.status"><option v-for="s in options.statuses" :key="s">{{s}}</option></select></label><label>Приоритет<select v-model="edit.priority"><option v-for="p in options.priorities" :key="p">{{p}}</option></select></label></div><label>Следующее действие<input v-model="edit.next_action"></label><label>Дата касания<input v-model="edit.next_at" type="date"></label><label>Комментарий<textarea v-model="edit.comment" rows="4"></textarea></label><button v-if="canEdit" class="primary">Сохранить</button><p v-else class="muted">{{free(detail)?'Сначала возьмите контакт в работу.':'Контакт закреплён за другим сотрудником.'}}</p></fieldset></form><p v-if="error" class="error">{{error}}</p><h3>История изменений</h3><div v-for="(h,i) in detail.history" :key="i" class="history"><strong>{{h.name}}</strong> · {{h.created_at}}<small>Изменены рабочие поля</small></div></section></div><div v-if="addOpen" class="overlay" @click.self="addOpen=false"><section class="drawer" role="dialog" aria-modal="true" aria-label="Новый контакт"><div class="page-head"><h2>Новый контакт</h2><button @click="addOpen=false">×</button></div><form @submit.prevent="create"><label v-for="[k,label] in [['full_name','ФИО'],['company_raw','Компания'],['title','Должность'],['email','Почта'],['phone','Телефон'],['messenger','Мессенджер'],['social','Соцсети']]" :key="k">{{label}}<input v-model="newLead[k]" :required="k==='full_name'"></label><button class="primary" :disabled="saving">Создать</button><p v-if="error" class="error">{{error}}</p></form></section></div>
<div v-if="assignment" class="overlay assignment-overlay" @click.self="!assignBusy&&(assignment=null)"><section class="drawer assignment-drawer" role="dialog" aria-modal="true" aria-label="Назначение ответственного"><div class="page-head"><h2>Назначить ответственного</h2><button :disabled="assignBusy" @click="assignment=null" aria-label="Закрыть">×</button></div><p>{{assignment.name}}</p><form @submit.prevent="assign(assignment,assignment.owner)"><label>Сотрудник<select v-model="assignment.owner" :required="user.role!=='admin'"><option v-if="user.role==='admin'" value="">Не назначен</option><option v-for="o in options.owners" :key="o.id" :value="o.id">{{o.name}}{{Number(o.id)===Number(user.id)?' (я)':''}}</option></select></label><p class="muted">В списке только сотрудники с доступом к Sales Hub.</p><button class="primary" :disabled="assignBusy">Назначить</button><p v-if="assignError" role="alert" class="error">{{assignError}}</p></form></section></div></div></AppLayout></template>
